window.CERT_DATA=window.CERT_DATA||{};window.CERT_DATA['adsp-42']={"round":42,"cert":"adsp","questions":[{"id":"82421","number":1,"category":"데이터 이해","type":"choice","subject":"다음중 데이터의 특성이 다른 하나는?","choices":[{"n":1,"html":"풍량"},{"n":2,"html":"강수량"},{"n":3,"html":"기상특보"},{"n":4,"html":"습도"}],"answer":[3],"explain":{"ai":["<p>데이터의 특성을 분석할 때, 주요한 차이점은 측정 대상의 본질과 표현 방식에 있다. 풍량, 강수량, 습도는 모두 연속적인 물리적 측정치로, 시간과 공간에 따라 변동하며 정확한 수치로 표현될 수 있다. 반면에, 기상특보는 이러한 연속적인 측정치가 아닌, 특정 조건 하에서의 분류나 경고 수준을 나타낸다. 즉, 기상특보는 수치적인 값보다는 상태나 등급(예: 주의보, 경보 등)을 표현하는 비수치적 특성을 가진다. 따라서 데이터의 본질적인 특성에서 다른 하나는 3번 기상특보다.</p>"]},"rate":94,"rateN":14452},{"id":"82422","number":2,"category":"데이터 이해","type":"choice","subject":"DIKW 피라미드 예시 중 맞는 것은?","choices":[{"n":1,"html":"D(Data): A마트는 100원, B마트는 200원에 연필을 판매한다."},{"n":2,"html":"I(Information): B마트가 A마트보다 연필이 100원 더 비싸다."},{"n":3,"html":"K(Knowledge): B가 A보다 연필이 더 싸니깐 B에서 사야겠다."},{"n":4,"html":"W(Wisdom): 문구류는 전반적으로 A마트가 더 저렴할 것이다."}],"answer":[3],"explain":{"ai":["<p>정답은 3번입니다. DIKW 피라미드는 데이터(D)에서 시작해 정보(I), 지식(K), 지혜(W)로 점차 높은 수준의 이해를 나타냅니다.</p>\n<ul>\n<li><strong>데이터(D)</strong>는 원시적인 사실을 의미합니다. 보기 1은 단순히 판매 가격의 숫자 데이터를 제공하므로 데이터에 해당합니다.</li>\n<li><strong>정보(I)</strong>는 데이터를 통해 얻을 수 있는 의미나 패턴을 포함합니다. 보기 2는 두 가격 간의 관계를 비교하여 얻은 정보이지만, 이는 사실 정보보다는 지식으로 분류될 수 있는 요소가 강합니다.</li>\n<li><strong>지식(K)</strong>는 정보를 바탕으로 한 해석과 이해를 의미합니다. 보기 3은 주어진 정보를 바탕으로 구매 결정을 내리는 데 필요한 실질적인 이해를 보여주므로 지식에 정확히 부합합니다.</li>\n<li><strong>지혜(W)</strong>는 광범위한 지식을 바탕으로 한 통찰력과 전략적 판단을 의미합니다. 보기 4는 특정 상황을 넘어 일반적인 추론을 제시하지만, 문제의 맥락에서는 지혜보다는 과도하게 일반화된 지식의 범주에 가깝습니다.</li>\n</ul>\n<p>따라서 주어진 보기 중에서 지식(K)의 정의에 가장 부합하는 것은 3번입니다.</p>"]},"rate":43,"rateN":16951},{"id":"82423","number":3,"category":"데이터 이해","type":"choice","subject":"데이터사이언티스트에게 필요한 역량이 아닌 것은?","choices":[{"n":1,"html":"스토리텔링"},{"n":2,"html":"비즈니스 분석기법"},{"n":3,"html":"네트워크 구축 역량"},{"n":4,"html":"통계적 사고능력"}],"answer":[3],"explain":{"ai":["<p>데이터사이언티스트의 핵심 역량은 데이터 분석, 의미 도출, 그리고 결과를 효과적으로 전달하는 데 집중됩니다. </p>\n<ol>\n<li><strong>스토리텔링</strong>은 분석 결과를 이해하기 쉽게 전달하는 데 필수적입니다.</li>\n<li><strong>비즈니스 분석기법</strong>은 데이터를 실제 비즈니스 문제 해결에 적용하는 데 중요합니다.</li>\n<li><strong>통계적 사고능력</strong>은 데이터 해석과 모델링에 근간이 됩니다.</li>\n</ol>\n<p>반면, 3번의 <strong>네트워크 구축 역량</strong>은 주로 IT 인프라 관리나 영업 분야에서 더 직접적으로 요구되는 능력입니다. 데이터사이언티스트로서 직접적인 핵심 역량은 아니므로, 이 문제의 정답은 3번입니다.</p>"]},"rate":63,"rateN":14317},{"id":"82424","number":4,"category":"데이터 이해","type":"choice","subject":"데이터베이스의 진행 절차를 올바른 순서대로 나열한 것은?","choices":[{"n":1,"html":"통합 - 저장 - 공유 - 변화"},{"n":2,"html":"저장 - 통합 - 변화 - 공유"},{"n":3,"html":"공유 - 저장 - 통합 - 변화"},{"n":4,"html":"변화 - 통합 - 저장 - 공유"}],"answer":[1],"explain":{"ai":["<p>데이터베이스의 진행 절차는 통합, 저장, 공유, 변화 순으로 진행된다. \n첫째, 데이터 수집 및 처리를 통해 통합한다. \n그 다음으로는 데이터를 저장하고, 이후에 데이터를 공유하게 된다.\n마지막으로 데이터의 값이나 형태가 변하는 과정을 거치게 된다.\n따라서 데이터베이스의 진행 절차를 올바른 순서대로 나열한 것은 1번이다. \n이 순서는 데이터베이스를 구축하고 운영하는 데 중요한 단계를 말하며, \n이러한 순서를 따라 데이터베이스를 구축하고 관리하면 효율적으로 데이터를 관리하고 분석할 수 있다.</p>"]},"rate":54,"rateN":15090},{"id":"82425","number":5,"category":"데이터 이해","type":"choice","subject":"빅데이터 위기 요인이 아닌 것은?","choices":[{"n":1,"html":"사생활 침해"},{"n":2,"html":"책임원칙훼손"},{"n":3,"html":"데이터오용"},{"n":4,"html":"분석기술의 발달"}],"answer":[4],"explain":{"ai":["<p>빅데이터 위기 요인을 살펴보면 주로 데이터의 양적 증가와 함께 발생하는 문제들로 이는 개인의 사생활 침해, 데이터 처리 과정에서 책임원칙의 허물어짐, 데이터의 오용 등이 있다. 반면에 분석기술의 발달은 빅데이터의 가능성을 높이고 신뢰성을 강화하기 위해 중요한 요소 중 하나다. 따라서 빅데이터 위기 요인이 아닌 것은 분석기술의 발달이다. 이는 데이터를 분석하고 해석하는 데 도움을 주기 때문에 위기 요인이 되기보다는 해결책으로 여겨진다.</p>"]},"rate":94,"rateN":12110},{"id":"82426","number":6,"category":"데이터 이해","type":"choice","subject":"빅데이터가 만들어내는 변화로 옳은 것은?","choices":[{"n":1,"html":"사후조사 → 사전예측"},{"n":2,"html":"표본조사 → 전수조사"},{"n":3,"html":"질적분석 → 양적분석"},{"n":4,"html":"인과관계 → 상관관계"}],"answer":[4],"explain":{"ai":["<p>정답은 4번입니다. 빅데이터의 핵심 특징 중 하나는 방대한 양의 데이터를 통해 패턴과 관계를 파악하는 데 있습니다. 이로 인해 과거에는 명확한 인과관계를 찾는 데 집중했던 접근법이 변화하여, 빅데이터 환경에서는 데이터 간의 상관관계를 더 쉽게 식별하고 활용하게 됩니다. </p>\n<p>1번은 빅데이터의 예측 분석 능력과 관련이 있지만, 주된 변화의 핵심은 아닙니다. 2번은 빅데이터가 실제로는 더 많은 데이터를 처리할 수 있게 함으로써 표본조사의 필요성을 줄이는 경향이 있지만, 전수조사로의 전환은 항상적인 변화라고 보기 어렵습니다. 3번은 분석 방법론의 선택 문제로, 빅데이터가 질적 분석에서 양적 분석으로의 전환을 강제하는 것은 아닙니다. 따라서 빅데이터 환경에서 가장 적절한 변화는 분석의 결과나 해석이 인과관계보다는 상관관계에 더 초점을 맞추게 되는 점입니다.</p>"]},"rate":31,"rateN":16092},{"id":"82427","number":7,"category":"데이터 이해","type":"choice","subject":"빅데이터가 미치는 영향이 아닌 것은?","choices":[{"n":1,"html":"고객에게 획일화된 서비스 제공"},{"n":2,"html":"맞춤형 서비스 확대"},{"n":3,"html":"업무 프로세스 최적화"},{"n":4,"html":"새로운 가치 창출"}],"answer":[1],"explain":{"ai":["<p>빅데이터의 주요 영향은 다양성과 개인화, 효율성 향상 및 혁신적 가치 창출에 있다. </p>\n<p>1번 보기의 \"고객에게 획일화된 서비스 제공\"은 빅데이터의 본질과 반대된다. 빅데이터는 방대한 양의 정보를 분석하여 고객의 개별적인 패턴과 선호도를 파악하게 해준다. 이로 인해 기업들은 각 고객에게 맞춤형 서비스를 제공할 수 있게 되어, 일괄적이고 동일한 서비스보다 훨씬 효과적이고 개인화된 접근이 가능해진다.</p>\n<p>반면, </p>\n<ul>\n<li>2번 \"맞춤형 서비스 확대\"는 빅데이터 분석을 통해 고객의 개별적인 필요를 충족시키는 데 핵심적이다.</li>\n<li>3번 \"업무 프로세스 최적화\"는 데이터 기반의 통찰력으로 효율성을 크게 높일 수 있다.</li>\n<li>4번 \"새로운 가치 창출\"은 빅데이터를 통해 새로운 시장 동향과 인사이트를 발견하며 가능하다.</li>\n</ul>\n<p>따라서, 빅데이터가 미치는 영향이 아닌 것은 고객 경험의 다양성과 개인화를 저해하는 \"1. 고객에게 획일화된 서비스 제공\"이다.</p>"]},"rate":85,"rateN":12122},{"id":"82428","number":8,"category":"데이터 이해","type":"choice","subject":"빅데이터의 사생활침해 해결방법은?","choices":[{"n":1,"html":"제공자 동의에서 사용자 책임으로 전환한다"},{"n":2,"html":"데이터 수집 범위를 제한한다"},{"n":3,"html":"개인정보 비식별화를 강화한다"},{"n":4,"html":"데이터 보안 시스템을 구축한다"}],"answer":[1],"explain":{"ai":["<p>제시된 해설은 정확하지 않습니다. 빅데이터의 사생활 침해 해결 방법에 대해 주어진 보기 중 가장 포괄적이고 효과적인 접근은 단일 옵션에 국한되지 않지만, 주어진 정답에 대해 수정된 해석을 제공하겠습니다.</p>\n<p><strong>해설:</strong></p>\n<p>주어진 정답 1번, \"제공자 동의에서 사용자 책임으로 전환한다\"는 부분적으로만 적용될 수 있는 접근법입니다. 그러나 최선의 해결 방안은 여러 가지 방법의 종합적 적용에 있습니다. </p>\n<ul>\n<li><strong>2. 데이터 수집 범위를 제한한다</strong>: 필요 최소한의 데이터만 수집하여 침해 위험을 줄입니다.</li>\n<li><strong>3. 개인정보 비식별화를 강화한다</strong>: 개인을 식별할 수 없는 형태로 데이터를 처리하여 사생활을 보호합니다.</li>\n<li><strong>4. 데이터 보안 시스템을 구축한다</strong>: 강력한 보안 시스템을 통해 데이터 유출과 불법 접근을 방지합니다.</li>\n</ul>\n<p>즉, <strong>가장 이상적인 해결 방법은 여러 옵션의 결합</strong>입니다. 하지만 주어진 정답에 따라, <strong>사용자 중심의 책임과 동의 절차 강화</strong>는 중요한 요소로, 이는 사용자 교육과 투명한 데이터 관리 정책을 통해 간접적으로 다른 방안들과 연계될 수 있습니다. 그럼에도 불구하고, 주어진 보기 중 가장 직접적인 개인 보호 측면의 변화를 강조한다면 1번이 선택될 수 있으나, 실제 적용에서는 2, 3, 4번의 요소들이 병행되어야 합니다.</p>"]},"rate":59,"rateN":13480},{"id":"82429","number":9,"category":"데이터 이해","type":"choice","subject":"빅데이터가 발전한 요인이 아닌 것은?","choices":[{"n":1,"html":"정형 데이터의 폭증"},{"n":2,"html":"하둡 등 분산처리 기술의 발전"},{"n":3,"html":"SNS 등 비정형 데이터의 증가"},{"n":4,"html":"클라우드 컴퓨팅의 발전"}],"answer":[1],"explain":{"ai":["<p>빅데이터의 발전 요인을 살펴보면, 주로 데이터의 양적 증가와 다양성, 그리고 효과적인 처리 기술의 발전에 초점을 맞춥니다. </p>\n<ul>\n<li>정형 데이터의 폭증(1번)은 빅데이터의 핵심 요인 중 하나로 흔히 언급되지만, 문제의 맥락에서는 다른 옵션들에 비해 직접적인 혁신 요인으로 분류되지 않습니다. 빅데이터의 진정한 특징은 다양한 형태의 데이터를 포괄하는 데 있습니다.</li>\n<li>분산처리 기술의 발전(2번)은 대용량 데이터를 효율적으로 처리할 수 있게 해주어 빅데이터 시대를 열었습니다.</li>\n<li>SNS 등 비정형 데이터의 증가(3번)는 텍스트, 이미지, 비디오 등 다양한 형태의 데이터를 포함시켜 빅데이터의 범위를 크게 확장시켰습니다.</li>\n<li>클라우드 컴퓨팅의 발전(4번)은 저장 및 처리 능력을 획기적으로 향상시켜 빅데이터 관리와 분석을 가능하게 했습니다.</li>\n</ul>\n<p>따라서, 빅데이터 발전의 혁신적인 변화 요인으로 보기에는 정형 데이터의 증가만이 상대적으로 한정적이므로, 정답은 1번입니다.</p>"]},"rate":80,"rateN":12484},{"id":"82430","number":10,"category":"데이터 이해","type":"choice","subject":"연결된 상태로 연결을 관리해야할 때를 설명하는 것은?","choices":[{"n":1,"html":"연결성"},{"n":2,"html":"디지털화"},{"n":3,"html":"에이전시"},{"n":4,"html":"네트워크 효과"}],"answer":[3],"explain":{"user":["에이전시는 정보의 비대칭성이 존재하는 상황에서 연결된 상태로 관리해야 하는 개념을 설명합니다."],"ai":["<p>에이전시(3번)는 각 구성 요소가 독립적으로 작동하는 개념에 가깝습니다. 문제에서 요구하는 바는 여러 요소 간의 지속적인 상호 연결과 그 연결의 관리입니다.</p>\n<p>연결성(1번)은 단순히 연결이 존재한다는 의미에 머물러 있어, 관리 측면을 명확히 포괄하지 못합니다. 디지털화(2번)는 데이터나 정보를 디지털 형태로 변환하는 과정을 의미하며, 연결 관리와 직접적인 관련이 없습니다. </p>\n<p>네트워크 효과(4번)는 연결된 요소의 수가 증가함에 따라 시스템의 가치가 상승하는 현상을 설명하지만, 본질적으로 연결 관리의 필요성을 직접적으로 다루지 않습니다.</p>\n<p>따라서, 문제에서 묻는 '연결을 관리해야 하는 상황'은 각 요소가 서로 상호작용하며 그 상호작용을 효과적으로 유지하고 조정할 수 있는 능력, 즉 <strong>에이전시</strong> 개념의 확장된 이해로 볼 수 있지만, 정확한 맥락에 따라 주어진 보기 중에서는 관리 측면을 가장 간접적으로라도 포괄할 수 있는 개념으로 해석하기 어렵습니다. </p>\n<p>그러나 주어진 보기 중에서 가장 적절한 답을 고르라는 출제 의도를 고려할 때, 문제의 핵심이 연결 관리의 필요성에 있다면, 주어진 옵션 중에서는 <strong>네트워크 효과(4번)</strong>가 연결된 상태에서 발생하는 복잡한 상호작용의 중요성을 암시하며, 그 관리의 필요성을 간접적으로 반영한다고 볼 수 있습니다. </p>\n<p>그러나 문제의 정확한 의도에 따라 정답이 3번 에이전시라고 제시되어 있으므로, 해설의 맥락상 <strong>에이전시</strong>는 각 요소의 자율성과 상호작용 관리의 필요성을 암시하지만, 주어진 보기와 문제 문맥에 따라 해석의 여지가 있다는 점을 명시해야 합니다. 출제 의도에 따라 정확한 정답은 <strong>3번 에이전시</strong>로 표기되었습니다. 이는 각 구성 요소 간의 복잡한 관계와 그 관리의 중요성을 강조하는 것으로 이해될 수 있습니다.</p>"]},"rate":38,"rateN":15036},{"id":"82431","number":11,"category":"데이터 분석 기획","type":"choice","subject":"KDD 분석방법론의 올바른 순서는?","choices":[{"n":1,"html":"Selection - Preprocessing - Transformation - Data Mining - Interpretation/Evaluation"},{"n":2,"html":"Preprocessing - Selection - Transformation - Data Mining - Interpretation/Evaluation"},{"n":3,"html":"Selection - Transformation - Preprocessing - Data Mining - Interpretation/Evaluation"},{"n":4,"html":"Preprocessing - Transformation - Selection - Interpretation/Evaluation - Data Minin"}],"answer":[1],"explain":{"user":["Selection - Preprocessing - Transformation - Data Mining - Interpretation/Evaluation\r\n\r\n해설: KDD 프로세스는 데이터 선택부터 평가까지 순차적으로 진행됩니다"],"ai":["<p>KDD 분석방법론은 데이터 마이닝의 프로세스를 정의한 프레임워크로 다음과 같은 단계로 구성된다. \nまず 데이터를 선택하는 선택 단계가 존재한다. \n다음으로 선택된 데이터의 품질을 높이고 일관성을 유지하기 위해 전처리 단계가 필요하다. \n전처리 단계 후 데이터를 분석에 적합한 형태로 변환하는 변환 단계를 수행한다. \n변환 단계 후 데이터 마이닝 단계를 통해 패턴이나 인사이트를 발견한다. \n마지막으로 발견된 지식을 해석하고 평가하는 해석 및 평가 단계가 있다. \n따라서 KDD 분석방법론의 올바른 순서는 선택, 전처리, 변환, 데이터 마이닝, 해석 및 평가 단계로 구성된다.</p>"]},"rate":63,"rateN":11134},{"id":"82432","number":12,"category":"데이터 분석 기획","type":"choice","subject":"전체 학생 중 한명을 뽑았더니 사과를 좋아할 확률은?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"4/10"},{"n":2,"html":"3/5"},{"n":3,"html":"1/2"},{"n":4,"html":"3/10"}],"answer":[1],"explain":{"user":["해설: 전체 100명 중 사과를 좋아하는 학생은 40명이므로 확률은 40/100 = 4/10입니다."]},"rate":93,"rateN":9946},{"id":"82433","number":13,"category":"데이터 분석 기획","type":"choice","subject":"CRISP-DM의 업무이해 단계로 맞는 것은?","choices":[{"n":1,"html":"업무 상황파악 - 데이터 마이닝 목표설정 - 프로젝트 계획 수립"},{"n":2,"html":"데이터 마이닝 목표설정 - 프로젝트 계획 수립 - 업무 상황파악"},{"n":3,"html":"프로젝트 계획 수립 - 업무 상황파악 - 데이터 마이닝 목표설정"},{"n":4,"html":"업무 상황파악 - 프로젝트 계획 수립 - 데이터 마이닝 목표설정"}],"answer":[1],"explain":{"ai":["<p>CRISP-DM은 데이터 마이닝 프로젝트를 체계적으로 진행하기 위한 프레임워크입니다. 업무이해 단계는 프로젝트의 목적과 범위를 정의하는 첫 단계입니다. \n업무 상황파악을 통해 비즈니스 목표와 요구사항을 이해하고, 데이터 마이닝 목표설정을 통해 구체적인 목표를 설정합니다. 이후 프로젝트 계획 수립을 통해 프로젝트의 범위와 계획을 정의하게 됩니다. \n따라서 업무이해 단계의 순서는 업무 상황파악, 데이터 마이닝 목표설정, 프로젝트 계획 수립의 순서로 진행됩니다. \n이러한 순서는 프로젝트를 체계적으로 진행하고, 비즈니스 목표를 달성하기 위한 중요한 단계입니다. \n따라서 정답은 1번이 됩니다.</p>"]},"rate":51,"rateN":12197},{"id":"82434","number":14,"category":"데이터 분석 기획","type":"choice","subject":"4V에서 비즈니스 효과에 해당하는 것은?","choices":[{"n":1,"html":"Value"},{"n":2,"html":"Volume"},{"n":3,"html":"Velocity"},{"n":4,"html":"Variety"}],"answer":[1],"explain":{"user":["4V 중 Value는 비즈니스 가치 창출을 의미합니다."],"ai":["<p>4V는 데이터의 특성을 설명하는 개념으로, Volume, Velocity, Variety, Value로 구성되어 있다. </p>\n<p>비즈니스 효과는 데이터가 가지는 가치 혹은 유용성을 의미한다. \n따라서 4V에서 비즈니스 효과에 해당하는 것은 Value이다. \nValue는 데이터가 비즈니스에 미치는 영향력 및 경제적 가치를 의미한다. \n즉, 데이터가 비즈니스에 가져다주는益이나 이익을 말한다. \n따라서 정답은 1번이다.</p>"]},"rate":79,"rateN":10633},{"id":"82435","number":15,"category":"데이터 분석 기획","type":"choice","subject":"프로세스 내재화에 대한 설명 중 분석 결과를 활용하고, 혁신 및 성과 향상에 기여하는 것은?","choices":[{"n":1,"html":"도입"},{"n":2,"html":"활용"},{"n":3,"html":"확산"},{"n":4,"html":"최적화"}],"answer":[4],"explain":{"user":["최적화 단계는 분석 결과를 적극 활용하여 프로세스를 개선하고 성과를 향상시키는 단계입니다."],"ai":["<p>데이터 분석 기획에서 프로세스 내재화는 데이터 분석을 조직 내에서 지속적으로 적용하고 향상하는 것을 의미합니다. 프로세스 내재화의 각 단계는 다음과 같습니다.</p>\n<ul>\n<li>도입(1): 새로운 데이터 분석 프로세스를 도입하는 초기 단계입니다.</li>\n<li>활용(2): 분석 결과를 실제業務에 적용하여 효용성을 높이는 단계입니다.</li>\n<li>확산(3): 데이터 분석을 조직 전체에 확대 적용하는 단계입니다.</li>\n<li>최적화(4): 분석 결과를 활용하여 지속적인 혁신과 성과 향상을 이루는 단계입니다.</li>\n</ul>\n<p>因此, 최적화 단계에서 분석 결과를 활용하고, 혁신 및 성과 향상에 기여합니다. 따라서 정답은 4번 최적화입니다. 이 단계에서는 데이터 분석을 통해 얻은 결과를 바탕으로 조직의 프로세스와 시스템을 개선하고, 새로운 기회를 tìm아내는 활동이 진행됩니다.</p>"]},"rate":47,"rateN":12477},{"id":"82436","number":16,"category":"데이터 분석 기획","type":"choice","subject":"상향식 방법론으로 옳지 않은 것은?","choices":[{"n":1,"html":"문제정의를 명확히 할 수 있을 때 사용한다"},{"n":2,"html":"데이터 중심의 접근방식이다"},{"n":3,"html":"데이터를 통해 인사이트를 도출한다"},{"n":4,"html":"탐색적 분석이 중심이 된다"}],"answer":[1],"explain":{"user":["상향식 방법론은 문제정의가 명확하지 않을 때 데이터 탐색을 통해 인사이트를 발견하는 방식입니다."],"ai":["<p>상향식 방법론은 데이터를 통해 문제를 파악하고 인사이트를 도출하는 방식입니다. 일반적으로 문제정의가 명확하지 않을 때 사용되며 데이터 중심의 접근방식입니다. 데이터를 분석하여 새로운 인사이트를 얻는 것이 주 목적이고 탐색적 분석이 중심이 됩니다. 따라서 문제정의를 명확히 할 수 있을 때 사용한다는 것은 상향식 방법론의 특성과 맞지 않습니다. 상향식 방법론은 데이터를 통해 문제를 정의하고 해결 방안을 찾는 데 중점을 두기 때문입니다.</p>"]},"rate":76,"rateN":10571},{"id":"82437","number":17,"category":"데이터 분석 기획","type":"choice","subject":"분석과제에서 고려해야할 요소가 아닌 것은?","choices":[{"n":1,"html":"데이터 크기(규모)"},{"n":2,"html":"속도"},{"n":3,"html":"복잡도"},{"n":4,"html":"데이터 분류"}],"answer":[4],"explain":{"user":["해설: 분석과제 수행 시 주요 고려요소는 데이터의 크기, 처리 속도, 분석 복잡도입니다."],"ai":["<p>데이터 분석과제를 진행할 때 고려해야 할 요소 중 데이터 분류는 일반적으로 고려해야 할 주요 요소는 아니기 때문이다. 데이터 크기, 속도, 복잡도는 데이터 분석과제의 난이도와 요구하는 리소스를 결정하는 중요한 요소들이다. 데이터 크기와 속도는 데이터를 처리하고 분석하는 데 걸리는 시간과 리소스를 결정짓고, 복잡도는 데이터를 분석하고 해석하는 데 걸리는 노력의 양을 결정한다. 데이터 분류는 특정 분석任务에서 중요할 수 있지만, 일반적으로 데이터 분석과제를 계획하는 초기 단계에서 주요 고려 대상은 아니다.</p>"]},"rate":58,"rateN":11877},{"id":"82438","number":18,"category":"데이터 분석 기획","type":"choice","subject":"시급성이 현재일 때 가장 먼저 고려할 것은?","choices":[{"n":1,"html":"전략적 중요도"},{"n":2,"html":"실현 가능성"},{"n":3,"html":"데이터 확보 용이성"},{"n":4,"html":"분석 난이도"}],"answer":[1],"explain":{"user":["시급성이 높은 과제는 전략적 중요도를 우선적으로 고려해야 합니다"],"ai":["<p>시급성이 현재일 때 가장 중요한 판단 기준은 긴급한 상황에서의 즉각적인 영향력과 필요성입니다. 이 경우, <strong>전략적 중요도(1번)</strong>가 가장 먼저 고려되어야 합니다. 전략적 중요도는 현재 상황에서 해당 데이터 분석이 조직의 목표 달성이나 문제 해결에 얼마나 핵심적인 역할을 하는지 평가합니다. 시급한 상황에서는 단순히 실행 가능성이나 데이터 수집의 용이성, 분석의 난이도보다, 그 분석 결과가 조직에 미치는 전략적 영향이 더 크게 작용하기 때문입니다. 따라서 즉각적인 의사결정과 행동에 가장 큰 가치를 제공할 수 있는 요소를 우선적으로 살펴봐야 하므로 1번이 정답입니다.</p>"]},"rate":42,"rateN":12721},{"id":"82439","number":19,"category":"데이터 분석 기획","type":"choice","subject":"데이터분석 준비시 고려의 중요도가 가장 낮은 것은?","choices":[{"n":1,"html":"비용"},{"n":2,"html":"분석업무이해"},{"n":3,"html":"분석문화"},{"n":4,"html":"분석기법"}],"answer":[1],"explain":{"user":["데이터분석의 성공을 위해서는 업무이해, 조직문화, 분석기법이 비용보다 더 중요한 고려사항입니다."],"ai":["<p>정답이 1번인 이유는 다음과 같습니다.</p>\n<p>데이터 분석 프로젝트 준비 과정에서 각 요소의 중요도를 살펴볼 때:</p>\n<ul>\n<li><strong>분석업무이해 (2)</strong>: 프로젝트의 목표와 필요한 분석 결과를 명확히 이해하는 것은 분석의 방향성과 성공 여부를 결정짓는 핵심 요소입니다.</li>\n<li><strong>분석문화 (3)</strong>: 조직 내에서 데이터 기반 의사결정이 얼마나 장려되고 실천되는지는 지속 가능한 분석 문화 구축에 필수적입니다.</li>\n<li><strong>분석기법 (4)</strong>: 적절한 통계적 또는 머신러닝 기법을 선택하는 것은 데이터 해석의 정확성과 신뢰성을 크게 좌우합니다.</li>\n</ul>\n<p>반면, <strong>비용 (1)</strong>은 중요한 고려사항이지만, 다른 요소들이 분석의 효과성과 정확성, 그리고 실행 가능성에 직접적인 영향을 미치는 반면, 비용은 이러한 핵심 요소들이 결정된 후에 조정 가능한 범위 내에서 관리되는 측면이 큽니다. 즉, 분석의 본질적인 성공과 직접적인 연관성이 상대적으로 낮기 때문에 중요도가 가장 낮게 평가됩니다. 따라서 정답은 1번입니다.</p>"]},"rate":46,"rateN":11977},{"id":"82440","number":20,"category":"데이터 분석 기획","type":"choice","subject":"협의의 데이터플랫폼의 구성요소인 것은?","choices":[{"n":1,"html":"분석 어플리케이션"},{"n":2,"html":"분석 서비스 제공 API"},{"n":3,"html":"분석 라이브러리"},{"n":4,"html":"분석 서비스 엔진"}],"answer":[3],"explain":{"user":["협의의 데이터플랫폼은 분석 라이브러리를 핵심 구성요소로 포함합니다."],"ai":["<p>데이터플랫폼은 데이터 수집, 저장, 처리, 분석, 시각화를 지원하는 플랫폼으로, 협의의 데이터플랫폼은 분석을 위한 도구와 라이브러리를 포함합니다. </p>\n<p>分析 라이브러리는 데이터 분석을 위한 함수와 알고리즘을 제공하는 소프트웨어 컴포넌트로, 데이터 분석에 필요한 다양한 기능을 지원합니다. </p>\n<p>따라서 분석 라이브러리는 협의의 데이터플랫폼의 구성요소로, 데이터 분석을 위한 다양한 함수와 알고리즘을 제공하여 데이터 분석 및 처리를 지원하는 중요한 요소입니다. </p>\n<p>따라서 정답은 3번인 분석 라이브러리입니다.</p>"]},"rate":49,"rateN":11612},{"id":"82441","number":21,"category":"데이터 분석","type":"choice","subject":"분석 방법은 알고 대상은 모를 때 사용할 수 있는 방법은?","choices":[{"n":1,"html":"발견"},{"n":2,"html":"통찰"},{"n":3,"html":"최적화"},{"n":4,"html":"솔루션"}],"answer":[2],"explain":{"user":["통찰은 분석 방법은 알지만 대상이 불명확할 때 사용하는 접근법입니다."],"ai":["<p>정답은 2번 '통찰'입니다. 데이터 분석 초기 단계에서 분석 방법은 이미 알고 있지만, 실제 데이터 내에서 어떤 패턴이나 정보가 중요한지 모를 때 '통찰' 기법이 주로 사용됩니다. 이 방법은 데이터를 깊이 탐색하여 예기치 않은 패턴이나 관계를 발견하는 데 초점을 맞춥니다. '발견'은 유사한 개념을 포함할 수 있지만, 맥락상 '통찰'이 데이터 내에서의 깊은 이해와 비정형적 정보의 추출에 더 적합합니다. '최적화'와 '솔루션'은 주로 특정 목표를 달성하기 위한 개선 방안이나 해결 방안을 찾는 과정에 초점을 맞추므로, 이 문제의 조건에는 맞지 않습니다.</p>"]},"rate":72,"rateN":9778},{"id":"82442","number":22,"category":"데이터 분석","type":"choice","subject":"회귀모형 선택방법에 대한 설명 중 틀린 것은?","choices":[{"n":1,"html":"AIC는 모형의 적합도와 복잡성을 고려한다"},{"n":2,"html":"R-제곱은 설명력을 나타내는 지표이다"},{"n":3,"html":"조정된 R-제곱은 변수 수를 고려한다"},{"n":4,"html":"BIC는 베이즈 정리에 기반하여 복잡한 모형에 더 큰 페널티를 부여한다"}],"answer":[4],"explain":{"ai":["<p>정답은 4번입니다. 설명에 따르면, 잘못된 문장은 \"BIC는 베이즈 정리에 기반하여 복잡한 모형에 더 큰 페널티를 부여한다\"입니다.  </p>\n<p>정확하게는, AIC(Akaike Information Criterion)와 BIC(Bayesian Information Criterion) 모두 모형의 복잡성에 대한 페널티를 적용하지만, BIC가 AIC보다 더 큰 페널티를 부여합니다. 그러나 BIC가 반드시 '베이즈 정리에 기반하여' 페널티를 부여한다는 표현은 엄밀히 말해 정확하지 않습니다. 베이즈 정리와 직접적인 연관성보다는, 이론적 배경에서 베이즈 추정과 유사한 방향성을 지니고 있다는 점에서 유래된 명칭일 뿐, 그 정의나 적용 방식은 주로 정보 기준의 측면에서 이해됩니다. 따라서 주어진 문장은 약간의 오해의 소지가 있어 틀린 것으로 간주됩니다.</p>\n<p>1번, 2번, 3번 문장은 각각 AIC의 성격, R-제곱의 역할, 그리고 조정된 R-제곱의 특성을 올바르게 설명하고 있습니다.</p>"]},"rate":50,"rateN":9934},{"id":"82443","number":23,"category":"데이터 분석","type":"choice","subject":"혼합분포군집에서 사용하는 알고리즘은?","choices":[{"n":1,"html":"EM 알고리즘"},{"n":2,"html":"K-means"},{"n":3,"html":"계층적 군집화"},{"n":4,"html":"DBSCAN"}],"answer":[1],"explain":{"user":["EM(Expectation-Maximization) 알고리즘은 혼합분포모형에서 주로 사용됩니다."],"ai":["<p>혼합분포군집은 데이터가 여러 가지 분포를 따라 생성된 경우를 모델링하는 방법입니다. 이 경우 데이터의 분포를 여러 가지 기본 분포의 혼합으로 모델링하며, 이때 사용되는 알고리즘이 바로 EM 알고리즘이라고 할 수 있습니다. EM 알고리즘은 기대값과 최대화의 두 단계를 반복하여 매개변수의 최대 가능도 추정치를 찾는 알고리즘입니다. 혼합분포의 매개변수를 추정할 때 많이 사용되며, 특히 데이터의 군집을 만들 때 각 데이터 포인트가 어느 군집에 속할지まだ 결정하지 않은 상황에서 많이 사용됩니다. </p>\n<p>다른 알고리즘들도 군집 분석에 사용되기는 하지만, 혼합분포군집에서는 특히 EM 알고리즘이 사용됩니다.</p>"]},"rate":42,"rateN":10688},{"id":"82444","number":24,"category":"데이터 분석","type":"choice","subject":"TV-라디오 R코드 해석 문제","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"TV와 라디오 사이의 교호관계가 있어 통계 모형이 유의하다"},{"n":2,"html":"TV:radio 통계 모형이 유의하다"},{"n":3,"html":"TV가 1 증가할 때 RADIO와 상관없이 SALES가 오른다"},{"n":4,"html":"모형의 설명력은 약 67%이다"}],"answer":[3],"rate":44,"rateN":9261},{"id":"82445","number":25,"category":"데이터 분석","type":"choice","subject":"분해시계열 요인 중 옳지 않은 것은?","choices":[{"n":1,"html":"추세요인"},{"n":2,"html":"계절요인"},{"n":3,"html":"교호요인"},{"n":4,"html":"순환요인"}],"answer":[3],"explain":{"user":["시계열 분해의 주요 요인은 추세, 계절, 순환, 불규칙 요인입니다."],"ai":["<p>분해시계열 분석은 시간에 따른 데이터의 변동성을 주요 요인들로 나누는 방법입니다. 주요 요인들은 다음과 같습니다:</p>\n<ul>\n<li><strong>추세요인</strong>: 장기적인 경향이나 방향성을 나타냅니다.</li>\n<li><strong>계절요인</strong>: 일정 주기로 반복되는 패턴을 반영합니다.</li>\n<li><strong>순환요인</strong>: 계절요인보다 긴 주기로 나타나는 경제적 또는 사회적 변동을 설명합니다.</li>\n</ul>\n<p>제시된 보기 중에서 <strong>교호요인</strong>은 분해시계열 분석의 표준 요인으로 분류되지 않습니다. 교호작용은 주로 다중 변수 간의 상호작용을 설명하는 데 사용되며, 시계열 데이터의 직접적인 분해 요인으로는 적절하지 않습니다. 따라서 옳지 않은 요인은 3번 <strong>교호요인</strong>입니다.</p>"]},"rate":77,"rateN":8616},{"id":"82446","number":26,"category":"데이터 분석","type":"choice","subject":"다음 중 지도학습이 아닌 것은?","choices":[{"n":1,"html":"로지스틱회귀분석"},{"n":2,"html":"의사결정나무"},{"n":3,"html":"인공신경망"},{"n":4,"html":"SOM"}],"answer":[4],"explain":{"user":["SOM(Self-Organizing Map)은 비지도학습 알고리즘입니다"],"ai":["<p>지도학습은 이미 레이블이 지정된 데이터를 통해 학습하는 방식입니다. 로지스틱회귀분석, 의사결정나무, 인공신경망은 모두 지도학습의 대표적인 알고리즘입니다. 로지스틱회귀분석은 분류 문제에 주로 사용되는 통계적 방법입니다. 의사결정나무는 트리 구조를 통해 데이터를 분류하는 알고리즘입니다. 인공신경망은 여러개의 층으로 구성된 신경망을 통해 데이터를 학습하는 방식입니다. </p>\n<p>반면에 SOM은 자율학습을 통해 데이터를 군집화하는 알고리즘입니다. SOM은 지도학습이 아닌 비지도학습에 해당합니다. 비지도학습은 레이블이 지정되지 않은 데이터를 통해 학습하는 방식이며, 데이터의 패턴이나 구조를 발견하는 데 사용됩니다. 따라서 SOM은 지도학습이 아닌 비지도학습의 알고리즘입니다.</p>"]},"rate":56,"rateN":9866},{"id":"82447","number":27,"category":"데이터 분석","type":"choice","subject":"회귀방정식 탐색방법 중 잘못된 것은?","choices":[{"n":1,"html":"후진선택법은 상수항만 남을때까지 제거한다"},{"n":2,"html":"전진선택법은 변수를 하나씩 추가한다"},{"n":3,"html":"단계적 선택법은 변수를 추가하거나 제거할 수 있다"},{"n":4,"html":"모든 가능한 회귀는 모든 조합을 검토한다"}],"answer":[1],"explain":{"user":["후진선택법은 통계적으로 유의하지 않은 변수를 제거하는 방식입니다."],"ai":["<p>후진선택법은 상수항만 남기고 시작하여 유의미한 변수들을 추가하는 방식이지, 제거만 하는 것이 아닙니다. 따라서 1번 보기의 설명은 잘못되었습니다.</p>\n<ul>\n<li>2번: 전진선택법은 실제로 가장 강력한 예측력을 가진 변수부터 차례대로 모델에 추가하는 방법으로 정확합니다.</li>\n<li>3번: 단계적 선택법은 변수를 필요에 따라 추가하거나 제거하여 최적의 모델을 찾아가는 방식이므로 올바르게 설명되어 있습니다.</li>\n<li>4번: 모든 가능한 조합을 검토하는 방법은 전결합법(all subsets regression)을 의미하며, 이 역시 올바른 설명입니다.</li>\n</ul>\n<p>결국, 잘못된 설명은 1번 보기입니다.</p>"]},"rate":47,"rateN":9935},{"id":"82448","number":28,"category":"데이터 분석","type":"choice","subject":"앙상블기법이 아닌 것은?","choices":[{"n":1,"html":"시그모이드"},{"n":2,"html":"배깅"},{"n":3,"html":"부스팅"},{"n":4,"html":"스태킹"}],"answer":[1],"explain":{"user":["시그모이드는 활성화함수이며, 나머지는 앙상블 학습 기법입니다."],"ai":["<p>앙상블기법이란 여러 개의 모델을 결합하여 예측 성능을 향상시키는 기법이다. </p>\n<p>배깅, 부스팅, 스태킹은 모두 앙상블기법 중 하나이다. </p>\n<p>배깅은 여러 개의 모델을 생성하여 투표를 통해 최종 예측값을 결정하는 방식이다. </p>\n<p>부스팅은 모델을 순차적으로 학습시켜서 예측 오차를 개선하는 방식이다. </p>\n<p>스태킹은 여러 개의 모델을 결합하여 메타 모델을 생성하는 방식이다. </p>\n<p>시그모이드는 다중 분류 문제에서 사용되는 활성화 함수로 앙상블기법이 아니다. </p>\n<p>따라서 시그모이드는 앙상블기법이 아님을 알 수 있다.</p>"]},"rate":72,"rateN":8789},{"id":"82449","number":29,"category":"데이터 분석","type":"choice","subject":"이상치를 이용하기에 가장 적절한 시스템인 것은?","choices":[{"n":1,"html":"부정구매 방지시스템"},{"n":2,"html":"추천시스템"},{"n":3,"html":"수요예측시스템"},{"n":4,"html":"고객분류시스템"}],"answer":[1],"explain":{"user":["이상치 탐지는 부정거래 탐지에 효과적으로 활용됩니다."],"ai":["<p>이상치는 데이터 집합에서 일반적인 패턴에서 크게 벗어나는 값들을 의미합니다. 이러한 특성 때문에 이상치 감지는 특이한 행동이나 오류를 식별하는 데 매우 효과적입니다.</p>\n<ol>\n<li>\n<p><strong>부정구매 방지시스템</strong>: 이 시스템은 정상적인 구매 패턴에서 벗어난 비정상적인 거래를 탐지하는데 이상치 분석이 핵심 역할을 합니다. 예를 들어, 평소와 다른 구매 금액이나 시간대, 위치 등의 이상 패턴은 부정 행위를 나타낼 가능성이 높아 이상치 탐지 기법이 적합합니다.</p>\n</li>\n<li>\n<p><strong>추천시스템</strong>: 주로 사용자의 행동 패턴과 선호도를 기반으로 유사한 데이터를 찾아 추천합니다. 이상치보다는 일반적인 패턴 분석에 더 초점을 맞춥니다.</p>\n</li>\n<li>\n<p><strong>수요예측시스템</strong>: 과거 데이터의 일반적인 흐름과 트렌드를 분석하여 미래의 수요를 예측합니다. 이상치는 예측 오류를 일으킬 수 있으므로, 주로 정상 범위 내의 데이터를 기반으로 합니다.</p>\n</li>\n<li>\n<p><strong>고객분류시스템</strong>: 고객을 특정 그룹으로 분류하는데, 이는 고객의 일반적인 특성과 행동 패턴을 분석하는 데 중점을 둡니다. 이상치는 분류 모델의 정확성을 저하시킬 수 있어 제한적으로 활용됩니다.</p>\n</li>\n</ol>\n<p>따라서 이상치를 효과적으로 활용하여 비정상적인 활동을 감지하고 대응해야 하는 맥락에서는 <strong>부정구매 방지시스템</strong>이 가장 적절합니다. 정답은 1번입니다.</p>"]},"rate":69,"rateN":9017},{"id":"82450","number":30,"category":"데이터 분석","type":"choice","subject":"매우만족 - 만족 - 보통 - 불만 - 매우 불만족은 무슨 척도인가?","choices":[{"n":1,"html":"서열척도"},{"n":2,"html":"명목척도"},{"n":3,"html":"구간척도"},{"n":4,"html":"비율척도"}],"answer":[1],"explain":{"user":["순서가 있으나 간격이 일정하지 않은 데이터는 서열척도입니다."],"ai":["<p>정답은 1. 서열척도입니다. 이 척도는 응답자의 의견이나 태도를 순위별로 분류하는데 사용됩니다. 매우만족부터 매우 불만족까지의 옵션은 각 응답 간에 순서가 명확하게 존재하지만, 그 사이의 간격이 동일하다는 보장은 없습니다. 예를 들어, 만족과 보통 사이의 차이와 보통과 불만 사이의 차이를 동일한 크기로 측정할 수 없습니다. 따라서 정확한 간격을 측정할 수 없고 단지 순위만을 나타내므로 서열척도에 해당합니다. 명목척도는 범주만 구분하고 순위가 없으며, 구간척도나 비율척도는 등간 간격이 존재한다는 특징이 있어 이 문제의 경우와 맞지 않습니다.</p>"]},"rate":57,"rateN":10113},{"id":"82451","number":31,"category":"데이터 분석","type":"choice","subject":"의사결정트리에서 범주형 변수에서의 분할방법에서 사용하는 것으로 옳지 않은 것은?","choices":[{"n":1,"html":"카이제곱 통계량"},{"n":2,"html":"지니지수"},{"n":3,"html":"엔트로피지수"},{"n":4,"html":"분산감소량"}],"answer":[4],"explain":{"user":["분산감소량은 연속형 변수의 분할에 사용됩니다."],"ai":["<p>의사결정트리에서 범주형 변수를 분할할 때 주로 사용되는 기준들은 불확실성이나 정보의 질을 측정하는 지표들에 기반합니다.</p>\n<ul>\n<li><strong>카이제곱 통계량</strong>은 범주형 데이터 간의 독립성을 검증하는데 사용되며, 분할 후 카테고리 분포의 차이를 측정합니다.</li>\n<li><strong>지니지수</strong>는 불순도를 측정하는 데 사용되어, 분할 후 각 클래스의 균일성을 평가합니다.</li>\n<li><strong>엔트로피지수</strong>는 정보 이론에서 유래한 것으로, 데이터의 무질서나 불확실성을 측정하여 최적의 분할을 찾습니다.</li>\n</ul>\n<p>반면, <strong>분산감소량</strong>은 주로 연속형 변수에서 사용되는 기준입니다. 연속형 데이터의 분산을 줄이는 방향으로 분할을 결정하는데 효과적이기 때문에, 범주형 변수의 분할 기준으로는 적절하지 않습니다. 따라서 옳지 않은 것은 4번, 분산감소량입니다.</p>"]},"rate":57,"rateN":9506},{"id":"82452","number":32,"category":"데이터 분석","type":"choice","subject":"주장하고자 하는 가설이 실제로는 예상보다 이상값이 도출될 확률이 높은 것은?","choices":[{"n":1,"html":"알파"},{"n":2,"html":"P-value"},{"n":3,"html":"베타"},{"n":4,"html":"1-알파"}],"answer":[2],"explain":{"ai":["<p>P-value는 귀무가설이 참이라는 가정 하에 관찰된 데이터나 더 극단적인 결과가 나올 확률을 나타냅니다. 만약 실제 상황에서 이상값이 예상보다 자주 발생할 가능성이 높다면, 이는 P-value가 낮지 않은 경우를 의미합니다. 즉, P-value가 통계적으로 유의미한 수준(일반적으로 0.05)을 초과할 가능성이 크다는 것을 시사합니다. 따라서 주장하고자 하는 가설에서 이상값이 예상보다 더 자주 도출될 확률이 높은 것은 P-value가 그 지표가 됩니다. 그러므로 정답은 2번 P-value입니다. 알파는 유의수준을, 베타는 제2종 오류의 확률을, 1-알파는 검정력을 나타내며, 이들은 직접적으로 이상값의 발생 빈도와 직접적인 관련이 없습니다.</p>"]},"rate":62,"rateN":9560},{"id":"82453","number":33,"category":"데이터 분석","type":"choice","subject":"다음에서 t통계량을 계산하시오","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"2.348 / 0.312 (회귀계수 / 오차)"},{"n":2,"html":"0.312 / 2.348 (오차 / 회귀계수)"},{"n":3,"html":"2.348 * 0.312 (회귀계수 * 오차)"},{"n":4,"html":"(2.348 + 0.312) / 2"}],"answer":[1],"explain":{"user":["여기서 t통계량(t value)은\r\n\r\n회귀계수(Estimate) / 표준오차(Std. Error)\r\n즉, 2.348 / 0.312 ≈ 7.526\r\n실제 R 결과에서 볼 수 있듯이, t통계량은 7.526으로 계산됩니다."]},"rate":51,"rateN":8033},{"id":"82454","number":34,"category":"데이터 분석","type":"choice","subject":"다음 표로부터 오분류율을 계산하시오.","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"13/20 = (FP + FN)/전체 = (8 + 5)/20 = 0.65"},{"n":2,"html":"(TP + TN)/전체 = (2 + 5)/20 = 0.35"},{"n":3,"html":"TP/(TP + FP) = 2/(2 + 8) = 0.2"},{"n":4,"html":"TN/(TN + FN) = 5/(5 + 5) = 0.5"}],"answer":[1],"explain":{"user":["오분류율은 잘못 분류된 케이스의 비율입니다."]},"rate":56,"rateN":8694},{"id":"82455","number":35,"category":"데이터 분석","type":"choice","subject":"보기의 내용을 통해 도출한 A질병 진단받은 사람 중 A질병 가진 사람 비율은?","extra":"<pre class=\"contents\">[보기]\r\n\r\n- 전체 중 A질병 가진사람: 10%\r\n\r\n- 전체 중 A질병 진단받은 사람: 20%\r\n\r\n- A질병 진단받은 사람 중 A질병을 실제 가진 사람: 90%</pre>","choices":[{"n":1,"html":"1/9"},{"n":2,"html":"2/9"},{"n":3,"html":"9/20"},{"n":4,"html":"9/10"}],"answer":[3],"explain":{"ai":["<p>A질병 진단받은 사람 중 A질병 가진 사람의 비율을 구하려면 A질병 진단받은 사람 중 실제로 A질병을 가진 사람의 비율과 전체 중 A질병 가진 사람의 비율을 이용해야 한다.</p>\n<p>전체 중 A질병 가진 사람의 비율은 10%이고 A질병 진단받은 사람 중 실제로 A질병을 가진 사람의 비율은 90%이다. 전체 중 A질병 진단받은 사람의 비율은 20%이다.</p>\n<p>A질병 진단받은 사람 중 A질병 가진 사람의 비율은 실제로 A질병을 가진 사람의 비율을 전체 중 A질병 진단받은 사람의 비율로 나눈 값과 같다. </p>\n<p>그러므로 A질병 진단받은 사람 중 A질병 가진 사람의 비율은 90%의 10%를 20%로 나눈 값 또는 9/20으로 계산된다. 따라서 도출한 A질병 진단받은 사람 중 A질병 가진 사람 비율은 9/20이다.</p>"]},"rate":40,"rateN":9108},{"id":"82456","number":36,"category":"데이터 분석","type":"choice","subject":"결측값에 대한 설명 중 틀린 것은?","choices":[{"n":1,"html":"완전연결법은 결측값 데이터를 완전히 삭제한다"},{"n":2,"html":"다중대치법은 여러번 대치하여 여러개의 자료를 도출한다"},{"n":3,"html":"확률단순선택법은 회귀분석을 사용한다"},{"n":4,"html":"평균표준편차는 중앙값으로 대체한다"}],"answer":[4],"explain":{"user":["평균대치법은 결측치를 평균으로 대체하는 방법입니다."],"ai":["<p>정답은 4번입니다. 해설은 다음과 같습니다:</p>\n<p>1번은 맞습니다. 완전연결법은 결측값이 있는 행 전체를 데이터셋에서 제거하는 방법을 의미합니다.</p>\n<p>2번도 올바르게 설명하고 있습니다. 다중대치법은 결측값을 여러 번 다른 값으로 대체함으로써 추가적인 가상의 데이터 세트를 생성할 수 있습니다.</p>\n<p>3번은 약간 혼동의 소지가 있지만, 일반적으로 확률적 방법은 결측값 대입에 사용되며, 이 과정에서 회귀분석이 종종 활용될 수 있다는 점에서 완전히 틀린 설명은 아닙니다. 그러나 이 문제의 맥락에서는 주요 오류가 아닌 것으로 간주됩니다.</p>\n<p>4번이 틀린 설명입니다. 평균이나 중앙값을 결측값 대체에 사용할 수는 있지만, 표준편차가 직접적으로 결측값을 대체하는 방법은 아닙니다. 결측값 처리에서 중앙값은 자주 사용되지만, 평균과 함께 쓰일 수 있고 표준편차 자체는 값의 변동 범위를 나타내는 지표로 결측값을 직접 대체하는 데에는 적합하지 않습니다. 따라서 이 문장은 개념적 오류를 포함하고 있습니다.</p>"]},"rate":47,"rateN":9627},{"id":"82457","number":37,"category":"데이터 분석","type":"choice","subject":"군집분석에서 군집수를 결정하는 방법은?","choices":[{"n":1,"html":"엘보우방법"},{"n":2,"html":"상관계수"},{"n":3,"html":"유클리드거리"},{"n":4,"html":"맨하탄거리"}],"answer":[1],"explain":{"user":["엘보우방법은 군집 내 분산의 감소율이 급격히 줄어드는 지점을 최적 군집수로 결정합니다."],"ai":["<p>군집분석은 데이터들을 유사한 특성을 가진 그룹으로 분류하는 통계기법입니다. 군집수를 결정하는 방법은 여러 가지가 있지만 엘보우 방법은 가장 대표적인 방법 중 하나입니다. 엘보우 방법은 데이터 세트에 대한 총 هر진성을 계산하여 군집의 수가 증가할 때 총 هر진성이 급격히 감소하는 지점을 찾습니다. 이를 통해 최적의 군집수를 결정할 수 있습니다.</p>\n<p>상관계수는 변수 간의 상관관계를 측정하는 지표로, 군집분석과는 관련이 없습니다. 유클리드 거리와 맨하탄 거리는 데이터 간의 거리를 측정하는 방법으로, 군집분석에서 데이터를 군집화 하는데 사용되지만, 군집수를 결정하는 방법은 아닙니다.</p>\n<p>따라서 군집수를 결정하는 방법으로 엘보우 방법을 사용하는 것이 적절합니다.</p>"]},"rate":49,"rateN":9757},{"id":"82458","number":38,"category":"데이터 분석","type":"choice","subject":"모집단이 정규분포를 따를때 신뢰구간 95%가 다음과 같이 계산된다. 이중 틀린 설명은?","extra":"<pre class=\"contents\">0.5 ± 1.96 / √100</pre>","choices":[{"n":1,"html":"신뢰구간 99%로 변경시 1.96대신 2.58이다"},{"n":2,"html":"표본평균이 0.5이다"},{"n":3,"html":"모집단의 평균값이 신뢰구간에 포함되지 않을 수 있다"},{"n":4,"html":"동일한 모집단에서 같은 방식으로 표본을 추출하고 같은 방식으로 신뢰구간을 추정하면 동일한 값이 나온다"}],"answer":[4],"explain":{"user":["표본추출이 달라지면 신뢰구간도 달라질 수 있습니다."],"ai":["<p>신뢰구간은 모집단의 평균값을 추정하는 통계학적 방법이다. 신뢰구간 95%는 모집단의 평균값이 구간 안에 있을 확률이 95%라는 것을 의미한다. </p>\n<p>지문에서 0.5 ± 1.96 / √100는 표본평균 0.5와 표준오차 1.96 / √100를 사용해 계산된 신뢰구간이다. </p>\n<p>1번은 신뢰구간 99%로 변경하면 1.96 대신 2.58이 사용됨을 설명하는 것으로, 이는 옳은 설명이다. </p>\n<p>2번은 표본평균이 0.5임을 설명하는 것으로, 이는 옳은 설명이다. </p>\n<p>3번은 모집단의 평균값이 신뢰구간에 포함되지 않을 수 있음을 설명하는 것으로, 이는 옳은 설명이다. </p>\n<p>4번은 동일한 모집단에서 같은 방식으로 표본을 추출하고 같은 방식으로 신뢰구간을 추정하면 동일한 값이 나온다는 것을 설명하는 것으로, 이는 틀린 설명이다. 신뢰구간은 표본의 확률 분포에 기반하기 때문에, 동일한 방법으로 추출하고 추정해도 결과는 달라질 수 있다. 따라서, 4번이 틀린 설명이다.</p>"]},"rate":54,"rateN":9136},{"id":"82459","number":39,"category":"데이터 분석","type":"choice","subject":"DBSCAN 관련하여 틀린 것은?","choices":[{"n":1,"html":"임의 형태의 군집으로 분류하는데 유용하다"},{"n":2,"html":"밀도기반 군집화 알고리즘이다"},{"n":3,"html":"초기 군집수 k를 설정해야한다"},{"n":4,"html":"다차원 자료의 경우 '차원의 저주'로 인해 유용하지않다"}],"answer":[3],"explain":{"user":["DBSCAN은 초기 군집수를 설정할 필요가 없는 알고리즘입니다."],"ai":["<p>DBSCAN은 밀도 기반의 군집 분석 알고리즘으로, 임의 형태의 데이터 군집을 효과적으로 식별할 수 있어 보기 1과 2는 정확하다. 그러나 보기 3은 틀렸다. DBSCAN의 특징 중 하나는 사용자가 미리 군집의 수(k)를 정의할 필요가 없다는 점이다. 이 알고리즘은 직접적으로 주변 데이터 포인트의 밀도를 기준으로 군집을 형성하므로, 초기 군집 수를 설정하는 k-means와 같은 알고리즘과 구별된다. 보기 4는 다소 오해의 소지가 있는데, DBSCAN은 차원의 저주에 직접적으로 영향을 받지만, 그 때문에 항상 유용하지 않다고 단정 짓기는 어렵다. 그럼에도 불구하고, 이 문제의 정답은 DBSCAN의 핵심 특성을 벗어난 <strong>3번</strong>이 맞다.</p>"]},"rate":54,"rateN":8939},{"id":"82460","number":40,"category":"데이터 분석","type":"choice","subject":"인공신경망관련 설명 중 틀린 것은?","choices":[{"n":1,"html":"은닉층이 적으면 과대적합, 은닉층 많으면 과소적합"},{"n":2,"html":"은닉층이 많을수록 복잡한 패턴을 학습할 수 있다"},{"n":3,"html":"활성화함수는 비선형성을 부여한다"},{"n":4,"html":"과적합을 방지하기 위해 드롭아웃을 사용할 수 있다"}],"answer":[1],"explain":{"user":["일반적으로 은닉층이 많으면 과대적합, 적으면 과소적합이 발생할 수 있습니다."],"ai":["<p>정답은 1번입니다. 설명은 다음과 같습니다:</p>\n<ul>\n<li>\n<p><strong>1번</strong>: 틀린 설명입니다. 실제로는 은닉층이 적을 경우 모델의 복잡도가 낮아져 학습 데이터에 과소적합(underfitting)될 가능성이 높아집니다. 반면, 은닉층이 지나치게 많아지면 모델이 과도하게 복잡해져 학습 데이터에 과대적합(overfitting)될 위험이 커집니다. 따라서 은닉층의 수와 과대적합/과소적합 간의 관계는 이 설명과 반대입니다.</p>\n</li>\n<li>\n<p><strong>2번</strong>: 올바른 설명입니다. 은닉층이 많아지면 신경망이 더 복잡한 함수와 패턴을 학습할 수 있는 능력이 증가합니다.</p>\n</li>\n<li>\n<p><strong>3번</strong>: 올바른 설명입니다. 활성화 함수는 신경망 노드의 출력에 비선형성을 도입하여 모델이 다양한 형태의 데이터 패턴을 효과적으로 학습할 수 있게 합니다.</p>\n</li>\n<li>\n<p><strong>4번</strong>: 올바른 설명입니다. 드롭아웃은 훈련 과정에서 일부 뉴런을 임의로 비활성화하여 모델의 일반화 성능을 향상시키고 과적합을 방지하는 기법입니다.</p>\n</li>\n</ul>"]},"rate":63,"rateN":8888},{"id":"82462","number":41,"category":"데이터 분석","type":"choice","subject":"신용카드 고객의 파산확률을 yes, no로 예측하기에 적절하지 않은 방법은?","choices":[{"n":1,"html":"선형회귀분석"},{"n":2,"html":"로지스틱 회귀분석"},{"n":3,"html":"랜덤포레스트"},{"n":4,"html":"SVM"}],"answer":[1],"explain":{"user":["이진분류 문제에는 선형회귀분석보다 로지스틱 회귀분석이 적합합니다."],"ai":["<p>선형회귀분석은 연속적인 숫자 값을 예측하는 데 주로 사용됩니다. 그러나 파산확률을 예측하는 경우 yes 또는 no와 같은 이진 분류 결과가 필요합니다. </p>\n<p>선형회귀분석은 이진 분류 문제에 적합하지 않습니다. 왜냐하면 선형회귀분석의 결과는 연속적인 값이기 때문입니다. </p>\n<p>로지스틱 회귀분석은 이진 분류 문제에 적합한 방법으로, yes 또는 no와 같은 결과를 예측하는데 사용됩니다. 랜덤포레스트와 SVM도 이진 분류 문제에 사용될 수 있습니다. </p>\n<p>따라서, 신용카드 고객의 파산확률을 yes, no로 예측하기에는 선형회귀분석이 적절하지 않습니다.</p>"]},"rate":41,"rateN":10642},{"id":"82463","number":42,"category":"데이터 분석","type":"choice","subject":"의사결정트리에서 더이상 세분화하지않고 멈출때 사용하는 기법은?","choices":[{"n":1,"html":"정지규칙"},{"n":2,"html":"가지치기"},{"n":3,"html":"비용복잡도"},{"n":4,"html":"교차검증"}],"answer":[1],"explain":{"user":["정지규칙은 트리의 성장을 멈추는 기준을 정의합니다."],"ai":["<p>의사결정트리에서 더 이상 세분화하지 않고 멈출 때 사용하는 기법은 정지규칙(Stopping Rule)입니다. </p>\n<p>의사결정트리 생성 과정에서 더 이상 나눌 수 없는 노드에 도달하거나, 추가로 분할해도 모델의 예측 성능이 개선되지 않을 때 트리 생성을 중단하기 위해 사용됩니다. </p>\n<p>일반적으로 노드의 샘플 수, 깊이, 불순度 등 특정 기준을 사용하여 트리 생성을 중단합니다. </p>\n<p>따라서 정답은 1번 정지규칙입니다. </p>\n<p>다른 보기인 가지치기(2번)은 트리 생성 후 과적합을 방지하기 위해 트리의 일부를 제거하는 기법입니다. </p>\n<p>비용복잡도(3번)와 교차검증(4번)은 의사결정트리 생성과 직접적으로 관련되지 않습니다. </p>\n<p>따라서 이 문제의 정답은 1번 정지규칙입니다.</p>"]},"rate":72,"rateN":8463},{"id":"82464","number":43,"category":"데이터 분석","type":"choice","subject":"다중공선성 해결방법으로 옳지 않은 것은?","choices":[{"n":1,"html":"중요도가 낮으면서 상관계수가 높은 변수를 제거한다"},{"n":2,"html":"구조적 다중공선성의 문제가 있는 경우에는 데이터의 평균 중심을 변화한다"},{"n":3,"html":"주성분분석을 통해 차원을 축소한다"},{"n":4,"html":"VIF를 이용하여 다중공선성 유무를 판단한다"}],"answer":[2],"explain":{"user":["구조적 다중공선성은 변수 변환이나 차원축소로 해결해야 합니다."],"ai":["<p>다중공선성은 독립 변수들 간에 높은 상관관계가 존재하여 분석 결과의 불안정성을 초래하는 문제다. 각 보기의 해결 방법들을 살펴보면:</p>\n<ol>\n<li>\n<p><strong>중요도가 낮으면서 상관계수가 높은 변수 제거</strong>: 이 방법은 직접적으로 관련 변수를 제거하여 다중공선성 문제를 완화하는 효과적인 전략이다.</p>\n</li>\n<li>\n<p><strong>데이터의 평균 중심을 변화시키는 것</strong>: 구조적 다중공선성은 주로 데이터 생성 과정의 본질적인 문제로 인해 발생하며, 단순히 데이터의 중심을 이동시키는 것은 이 문제를 해결하지 못한다. 따라서 이는 적절한 해결 방법이 아니다.</p>\n</li>\n<li>\n<p><strong>주성분분석(PCA) 사용</strong>: PCA는 고차원 데이터를 몇 개의 주요 성분으로 축소시켜 다중공선성을 감소시키는 효과적인 기법이다.</p>\n</li>\n<li>\n<p><strong>VIF(분산팽창요인) 활용</strong>: VIF는 다중공선성의 정도를 측정하는 지표로, 이를 통해 문제의 유무와 심각성을 판단할 수 있다.</p>\n</li>\n</ol>\n<p>따라서 옳지 않은 해결 방법은 <strong>2번</strong>이다. 데이터 중심 이동은 구조적 다중공선성의 근본적인 원인을 해결하지 못한다.</p>"]},"rate":49,"rateN":9879},{"id":"82465","number":44,"category":"데이터 분석","type":"choice","subject":"다중회귀모형에서 통계적으로 유의함을 판단할때 사용하는 검증은?","choices":[{"n":1,"html":"F검정"},{"n":2,"html":"P-VALUE"},{"n":3,"html":"T통계량"},{"n":4,"html":"Z통계량"}],"answer":[1],"explain":{"user":["다중회귀모형의 전체적인 유의성은 F검정으로 판단합니다."],"ai":["<p>다중회귀모형에서 전체적인 모델의 유의성을 판단할 때 주로 사용하는 검증 방법은 F검정입니다. F검정은 모델 내의 모든 독립변수들이 종속변수에 통계적으로 유의미한 영향을 미치는지 평가하는데 사용됩니다. </p>\n<ul>\n<li><strong>P-VALUE</strong>는 각 개별 독립변수의 유의성을 판단하는 데 주로 사용됩니다.</li>\n<li><strong>T통계량</strong>은 단일 독립변수가 종속변수에 미치는 영향을 검정할 때 활용됩니다.</li>\n<li><strong>Z통계량</strong>은 표본 크기가 충분히 클 때 사용되며, 일반적으로 단순회귀에서 더 자주 등장합니다.</li>\n</ul>\n<p>따라서 모델 전체의 유의성을 판단하는 데는 F검정이 적합하며, 이로 인해 정답은 1번입니다.</p>"]},"rate":54,"rateN":9532},{"id":"82466","number":45,"category":"데이터 분석","type":"choice","subject":"데이터 베이스의 특징 중 ( ) 안에 들어갈 내용으로 알맞은 것은?","extra":"<pre class=\"contents\">1. ( )데이터는 동일한 내용이 중복되지않게 함\r\n\r\n2. ( )데이터는 컴퓨터가 접근할 수있는 매체에 저장\r\n\r\n3. ( )데이터는 여러 사용자가 함께 사용가능\r\n\r\n4. ( )데이터는 항상 변화해도 현재의 정확한 데이터를 유지해야함</pre>","choices":[{"n":1,"html":"공용 - 저장 - 통합 - 변화되는"},{"n":2,"html":"저장 - 통합 - 공용 - 변화되는"},{"n":3,"html":"통합된 - 저장 - 공용 - 변화되는"},{"n":4,"html":"통합된 - 공용 - 변화되는 - 저장"}],"answer":[3],"explain":{"ai":["<p>데이터 베이스의 특징은 여러 가지가 있다. \n첫째, 데이터는 동일한 내용이 중복되지 않게 하는 것이 중요하다. \n이는 데이터의 일관성을 유지하기 위함이다. \n따라서 첫 번째 빈칸에는 통합된이 들어가야 한다. </p>\n<p>둘째, 데이터는 컴퓨터가 접근할 수 있는 매체에 저장되어야 한다. \n이것은 데이터를 효율적으로 관리하고 접근할 수 있도록 한다. \n따라서 두 번째 빈칸에는 저장이 들어가야 한다. </p>\n<p>셋째, 데이터는 여러 사용자가 함께 사용할 수 있도록 해야 한다. \n이것은 데이터를 공유하고 협업할 수 있도록 하는데 중요한 특징이다. \n따라서 세 번째 빈칸에는 공용이 들어가야 한다. </p>\n<p>넷째, 데이터는 항상 변화하고 있지만 현재의 정확한 데이터를 유지해야 한다. \n이것은 데이터의 신뢰성을 유지하기 위함이다. \n따라서 네 번째 빈칸에는 변화되는이 들어가야 한다. \n따라서 데이터 베이스의 특징 중 빈칸에 들어갈 내용으로 알맞은 것은 통합된 - 저장 - 공용 - 변화되는이다.</p>"]},"rate":84,"rateN":8317},{"id":"82467","number":46,"category":"데이터 분석","type":"choice","subject":"이상값에 대한 설명 중 틀린 것은?","choices":[{"n":1,"html":"범위의 경우 이상값 존재시 값이 커진다는 단점이 있다"},{"n":2,"html":"평균대치법에는 조건부 평균대치법, 비조건부 평균대치법이 있다"},{"n":3,"html":"이상값은 데이터의 품질을 저하시킬 수 있다"},{"n":4,"html":"평균절대편차법은 중앙값이랑 변수 사이의 차이값들로 이루어진 것을 의미한다"}],"answer":[4],"explain":{"ai":["<p>정답은 4번입니다. 설명은 다음과 같습니다:</p>\n<p>4번은 틀렸습니다. 평균절대편차법은 각 데이터 값이 평균으로부터 얼마나 떨어져 있는지를 측정하는 방법으로, 각 데이터 값과 <strong>평균</strong> 사이의 절대 차이의 평균을 계산합니다. 여기서 중앙값과 직접적인 관련이 없습니다. 중앙값은 데이터를 정렬했을 때 중앙에 위치하는 값이며, 평균절대편차법은 이와 무관하게 평균을 기준으로 편차를 측정합니다.</p>\n<p>다른 보기들의 정확성은 다음과 같습니다:</p>\n<ol>\n<li>이상값이 존재하면 데이터의 범위가 커질 수 있다는 설명은 맞습니다. 이상값은 극단적으로 높거나 낮은 값으로 범위를 확장시킵니다.</li>\n<li>평균대치법의 두 유형인 조건부와 비조건부 평균대치법에 대한 설명은 정확합니다.</li>\n<li>이상값이 데이터 품질을 저하시킬 수 있다는 설명도 올바르며, 통계적 분석 결과의 신뢰성을 떨어뜨릴 수 있다는 점에서 맞습니다.</li>\n</ol>"]},"rate":56,"rateN":9336},{"id":"82468","number":47,"category":"데이터 분석","type":"choice","subject":"자기상관모형에 대한 설명으로 맞는 것은?","choices":[{"n":1,"html":"ARIMA는 비정상 시계열에만 사용한다"},{"n":2,"html":"MA(q)는 과거의 관측값에 의존한다"},{"n":3,"html":"계절성 ARIMA는 주기성을 고려하지 않는다"},{"n":4,"html":"AR(1)은 1개의 시차, AR(2)는 2개의 시차 사용한다"}],"answer":[4],"explain":{"ai":["<p>정답은 4번입니다.</p>\n<p>자기상관모형에 대한 올바른 설명은 다음과 같습니다:</p>\n<ul>\n<li>1번은 틀렸습니다. ARIMA 모델은 정상 시계열과 비정상 시계열 모두에 사용됩니다. 비정상 시계열의 경우 차분을 통해 정상화를 시도합니다.</li>\n<li>2번은 부정확합니다. MA(q) 모형은 과거의 오차항에 의존하지, 직접 과거의 관측값에 의존하는 것이 아닙니다.</li>\n<li>3번은 명백히 틀렸습니다. 계절성 ARIMA (SARIMA) 모형은 데이터 내의 주기성을 정확히 고려하여 분석합니다.</li>\n<li>4번은 정확합니다. AR(p) 모형에서 p는 고려하는 과거의 시차 수를 나타냅니다. 따라서 AR(1)은 직전 1기의 값, AR(2)는 직전 2기의 값들을 사용합니다.</li>\n</ul>"]},"rate":51,"rateN":9084},{"id":"82469","number":48,"category":"데이터 분석","type":"choice","subject":"회귀모형의 가정에 대한 설명으로 옳은 것은?","choices":[{"n":1,"html":"잔차는 서로 독립이어야 한다"},{"n":2,"html":"설명변수 간에는 높은 상관관계가 있어야 한다"},{"n":3,"html":"잔차의 분산은 불균일해야 한다"},{"n":4,"html":"잔차는 비정규분포를 따라야 한다"}],"answer":[1],"wiki":[{"title":"OLS 회귀분석","url":"https://itwiki.kr/w/OLS 회귀분석"}],"explain":{"ai":["<p>회귀모형의 가정 중에서 가장 중요한 조건은 데이터의 잔차가 특정한 독립성과 정규성을 따르는 것이다. 올바른 설명은 다음과 같다:</p>\n<ol>\n<li>\n<p><strong>잔차는 서로 독립이어야 한다</strong>: 이는 회귀 모형의 핵심 가정 중 하나로, 각 관측치의 오차가 다른 관측치의 오차와 연관되지 않아야 한다는 의미다. 이 조건이 충족되지 않으면 예측력과 신뢰성에 문제가 생길 수 있다.</p>\n</li>\n<li>\n<p><strong>설명변수 간 높은 상관관계</strong>: 잘못된 설명이다. 설명변수들 간의 높은 상관관계는 다중공선성 문제를 일으켜 모형의 안정성과 해석력을 저하시킨다. 그러므로 설명변수들 간의 상관관계는 가능한 낮아야 한다.</p>\n</li>\n<li>\n<p><strong>잔차의 분산은 불균일해야 한다</strong>: 부정확하다. 잔차의 분산은 일정하게 유지되어야 한다는 등분산성 가정이 필요하다. 분산이 불균일하면 (즉, heteroscedasticity), 모형의 예측 오차가 일관되지 않게 된다.</p>\n</li>\n<li>\n<p><strong>잔차는 비정규분포를 따라야 한다</strong>: 잘못된 주장이다. 회귀분석에서는 잔차가 정규분포를 따르는 것이 바람직하다. 정규성 가정이 깨지면 신뢰구간과 가설 검정 결과에 오류가 생길 수 있다.</p>\n</li>\n</ol>\n<p>따라서 정답은 <strong>1번</strong>이다. 잔차의 독립성이 회귀 분석의 신뢰성을 보장하는 중요한 가정 중 하나이기 때문이다.</p>"]},"rate":58,"rateN":9187},{"id":"82470","number":49,"category":"데이터 분석","type":"choice","subject":"A를 선택할 확률 대비 B와 A를 같이 팔 때 얼마나 더 많이 팔리는가?","choices":[{"n":1,"html":"지지도"},{"n":2,"html":"신뢰도"},{"n":3,"html":"향상도"},{"n":4,"html":"재현율"}],"answer":[3],"explain":{"user":["향상도는 두 아이템의 연관성 강도를 나타내는 지표입니다."],"ai":["<p>향상도는 항목 A가 주어졌을 때 항목 B의 추가적 판매 증가율을 측정하는 지표입니다. 이는 A 선택 시와 비교했을 때 A와 B를 함께 판매했을 때의 판매 증가 효과를 직접적으로 보여줍니다. </p>\n<p>지지도는 단순히 A 또는 B가 단독으로 얼마나 자주 선택되는지를 나타내며, 신뢰도는 A가 선택되었을 때 B가 함께 선택될 확률을 보여줍니다. 재현율은 주로 분류 모델의 성능을 평가할 때 사용되며, 실제 양성 데이터 중 얼마나 정확히 양성으로 예측되었는지를 의미합니다.</p>\n<p>따라서, 문제에서 요구하는 \"A 선택 시 대비 A와 B 함께 판매 시의 판매 증가량\"을 정확히 표현하는 것은 향상도입니다. 그러므로 정답은 3번, 향상도입니다.</p>"]},"rate":47,"rateN":10004},{"id":"82471","number":50,"category":"데이터 분석","type":"choice","subject":"apriori 알고리즘에 대한 설명으로 옳은 것은?","choices":[{"n":1,"html":"순차적 패턴을 찾는데 사용된다"},{"n":2,"html":"군집분석에 주로 활용된다"},{"n":3,"html":"최소 지지도를 가정으로 한다"},{"n":4,"html":"연속형 변수에만 적용 가능하다"}],"answer":[3],"explain":{"user":["Apriori 알고리즘은 최소 지지도를 기준으로 빈발 항목집합을 찾습니다."],"ai":["<p>apriori 알고리즘은 연관규칙학習에 사용되는 알고리즘으로 최소 지지도를 가정으로 한다. 데이터에서 자주 나타나는 연관 규칙을 찾는 데 사용된다. 최소 지지도는 데이터 안에서 특정 아이템셋이 나타날 최소 빈도를 의미한다. </p>\n<p>apriori 알고리즘은 데이터에서 빈번하게 나타나는 항목들의 집합을 찾아내고, 이를 통해 의미 있는 연관 규칙을 도출한다. 이 알고리즘은 주로 시장 바스ケット 분석에 사용된다. 순차적 패턴을 찾는 것은 아니며, 군집분석과는 관련이 없고, 연속형 변수에만 적용되는 것이 아니다. 따라서 정답은 3번이다.</p>"]},"rate":44,"rateN":9911}]};